/// Registered customer accounts with email and password credentials for
/// shopping operations. This table serves as the primary identity record for
/// customers who can browse products, add items to cart, place orders, write
/// reviews, and manage their profiles and addresses. Customer accounts
/// support soft deletion to preserve order history and reviews while
/// removing personal credentials.
///
/// Related entities: {@link shopping_mall_customer_sessions} for
/// authentication sessions, {@link shopping_mall_customer_password_resets}
/// for account recovery, {@link shopping_mall_customer_email_verifications}
/// for email confirmation, {@link shopping_mall_orders} for purchase
/// history, {@link shopping_mall_reviews} for product feedback.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's email address used for authentication and communication. Must
  /// be unique across all customer accounts.
  email String

  /// Bcrypt hashed password for customer authentication. Never stores plain
  /// text passwords.
  password_hash String

  /// Customer's display name shown in reviews and public-facing content. Can
  /// be updated by the customer.
  nickname String

  /// Customer's contact phone number for order notifications and delivery
  /// coordination.
  phone_number String

  /// Timestamp when the customer account was created. Used for auditing and
  /// account age verification.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was last updated. Tracks profile
  /// modifications and credential changes.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was soft deleted. Null for active
  /// accounts. Preserves order history and reviews while removing
  /// authentication credentials.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions shopping_mall_customer_sessions[]
  passwordResets shopping_mall_customer_password_resets[]
  emailVerifications shopping_mall_customer_email_verifications[]
  wishlists shopping_mall_wishlists[]
  cart shopping_mall_carts?
  orders shopping_mall_orders[]
  reviews shopping_mall_reviews[]
  reviewSnapshots shopping_mall_review_snapshots[]
  cancellationRequests shopping_mall_cancellation_requests[]
  refundRequests shopping_mall_refund_requests[]
  refundRequestSnapshots shopping_mall_refund_request_snapshots[]
  adminRequests shopping_mall_admin_requests[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([created_at])
  @@index([nickname(ops: raw("gin_trgm_ops"))], type: Gin)
}

