/// Registered seller accounts with email/password credentials for product
/// management and order processing. Sellers require administrator approval
/// before they can list products and manage inventory. This table serves as
/// the canonical identity record for the seller actor type, with
/// authentication credentials and shop profile attributes. Sessions are
/// tracked in {@link shopping_mall_seller_sessions}, password resets in
/// {@link shopping_mall_seller_password_resets}, and email verifications in
/// {@link shopping_mall_seller_email_verifications}.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Administrator who approved or rejected this seller account. {@link
  /// shopping_mall_admins.id}.
  approved_by_admin_id String? @db.Uuid

  /// Unique email address for seller authentication and communication.
  email String

  /// Bcrypt hashed password for seller authentication.
  password_hash String

  /// Display name of the seller's shop or store.
  shop_name String

  /// Detailed description of the shop's products, brand, and business.
  shop_description String?

  /// URL to the shop's logo or brand image.
  logo_image_url String? @db.VarChar(80000)

  /// Admin approval status: PENDING (awaiting review), APPROVED (can list
  /// products), REJECTED (application denied).
  approval_status String

  /// Reason provided by administrator if approval was rejected.
  rejection_reason String?

  /// Whether the seller account is temporarily suspended. Suspended sellers
  /// cannot create or edit products but can process existing orders.
  suspended Boolean

  /// Timestamp when the seller account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was soft deleted. Null if account is
  /// active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  approvedByAdmin shopping_mall_admins? @relation(fields: [approved_by_admin_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions shopping_mall_seller_sessions[]
  passwordResets shopping_mall_seller_password_resets[]
  emailVerifications shopping_mall_seller_email_verifications[]
  products shopping_mall_products[]
  productSnapshots shopping_mall_product_snapshots[]
  orderItems shopping_mall_order_items[]
  respondedCancellationRequests shopping_mall_cancellation_requests[]
  cancellationRequestSnapshots shopping_mall_cancellation_request_snapshots[]
  refundRequests shopping_mall_refund_requests[]
  refundRequestSnapshots shopping_mall_refund_request_snapshots[]

  //----
  // INDEXES
  //----
  @@index([approved_by_admin_id])
  @@unique([email])
  @@index([approval_status, created_at])
  @@index([shop_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// JWT session tokens for seller authentication with access and refresh
