  /// Belonged seller's {@link shopping_mall_sellers.id}.
  shopping_mall_seller_id String @db.Uuid

  /// IP address of the client connection for security auditing and session
  /// tracking.
  ip String

  /// Full URL of the login request for connection context tracking.
  href String

  /// HTTP referrer header indicating the page that initiated the login request.
  referrer String

  /// Timestamp when the session was created (login time).
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expires and becomes invalid for security
  /// enforcement.
  expired_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  seller shopping_mall_sellers @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade)

