    paginatedActiveResult.pagination.current,
    2,
  );
  TestValidator.equals(
    "pagination limit",
    paginatedActiveResult.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    () => paginatedActiveResult.pagination.pages >= 0,
  );
}

