  for (let i = 1; i < combinedFilterResult.data.length; i++) {
    TestValidator.predicate(
      `combined filter - email sort at index ${i}`,
      combinedFilterResult.data[i - 1].email <=
        combinedFilterResult.data[i].email,
    );
