  if (sortedResponse.data.length > 1) {
    for (let i = 0; i < sortedResponse.data.length - 1; i++) {
      const currentTime = new Date(sortedResponse.data[i].created_at).getTime();
      const nextTime = new Date(
        sortedResponse.data[i + 1].created_at,
