/**
 * Test seller creating a product variant option.
 *
 * This test validates the complete workflow:
 * 1. Seller registers and authenticates
 * 2. Seller creates a product with required fields
 * 3. Seller creates a variant under the product
 * 4. Seller adds an option key-value pair to the variant
 * 5. Validate option is created with correct structure and relationships
 */
export async function test_api_product_variant_option_creation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller authentication via join
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
      shop_description: RandomGenerator.paragraph({ sentences: 2 }),
      logo_image_url: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerAuth);
  // 2. Create a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      },
    },
  );
  typia.assert(product);
  // 3. Create a variant under the product
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku_code: `SKU-${RandomGenerator.alphaNumeric(12)}`,
          price: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
          stock_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<100>
          >(),
          options: [],
        },
      },
    );
  typia.assert(variant);
  // 4. Add an option to the variant
  const option =
    await generate_random_shopping_mall_seller_products_variants_options_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          key: "color",
          value: "Red",
        } satisfies IShoppingMallProductVariantOption.ICreate,
      },
    );
  typia.assert(option);
  // 5. Validate business logic (not types - typia.assert handles that)
  TestValidator.equals("option key matches input", option.key, "color");
  TestValidator.equals("option value matches input", option.value, "Red");
  TestValidator.equals(
    "variant relationship preserved",
    option.variant.id,
    variant.id,
  );
  TestValidator.equals(
    "variant skuCode matches",
    option.variant.skuCode,
    variant.skuCode,
  );
}

