/**
 * Test that an administrator can retrieve snapshots of a deleted product for audit and dispute resolution purposes.
 *
 * This test validates the business requirement that product snapshots remain accessible after product deletion
 * for record-keeping and dispute resolution. The test flow:
 * 1. Authenticate as administrator
 * 2. Create and authenticate a seller account
 * 3. Create a product with the seller
 * 4. Edit the product multiple times to generate snapshots
 * 5. Delete the product (soft delete)
 * 6. Call the admin snapshot list endpoint with the deleted product's ID
 * 7. Verify snapshots are returned with preserved data integrity
 */
export async function test_api_product_snapshot_deleted_product_access(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin authentication
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.IJoin,
  });
  typia.assert(adminAuth);
  TestValidator.equals("admin grade", adminAuth.grade, "ADMIN");
  // 2. Create seller account
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
      shop_description: RandomGenerator.paragraph({ sentences: 2 }),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerAuth);
  // 3. Create product with seller
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 1 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      },
    },
  );
  typia.assert(product);
  TestValidator.predicate("product has id", product.id !== undefined);
  // Store original product data for snapshot validation
  const originalName = product.name;
  const originalPrice = product.base_price;
  const originalDescription = product.description;
  // 4. Edit product multiple times to create snapshots
  const updatedName = RandomGenerator.paragraph({ sentences: 1 });
  const updateResult1 =
    await api.functional.shoppingMall.seller.products.update(sellerConnection, {
      productId: product.id,
      body: {
        name: updatedName,
      } satisfies IShoppingMallProduct.IUpdate,
    });
  typia.assert(updateResult1);
  TestValidator.equals("name updated", updateResult1.name, updatedName);
  const updatedPrice = typia.random<
    number & tags.Type<"uint32"> & tags.Minimum<2000>
  >();
  const updateResult2 =
    await api.functional.shoppingMall.seller.products.update(sellerConnection, {
      productId: product.id,
      body: {
        basePrice: updatedPrice,
      } satisfies IShoppingMallProduct.IUpdate,
    });
  typia.assert(updateResult2);
  TestValidator.equals("price updated", updateResult2.base_price, updatedPrice);
  // 5. Delete the product (soft delete)
  await api.functional.shoppingMall.seller.products.erase(sellerConnection, {
    productId: product.id,
  });
  // 6. Admin retrieves snapshots of deleted product
  const snapshotResponse =
    await api.functional.shoppingMall.admin.products.snapshots.index(
      adminConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          limit: 10,
          sort: "snapshot_at,desc",
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );
  typia.assert(snapshotResponse);
  // 7. Validate snapshot data integrity
  TestValidator.predicate(
    "snapshots exist for deleted product",
    snapshotResponse.data.length > 0,
  );
  TestValidator.equals(
    "pagination current page",
    snapshotResponse.pagination.current,
    1,
  );
  TestValidator.predicate(
    "pagination has records",
    snapshotResponse.pagination.records > 0,
  );
  // Validate each snapshot has required fields preserved
  for (const snapshot of snapshotResponse.data) {
    TestValidator.predicate("snapshot has id", snapshot.id !== undefined);
    TestValidator.predicate(
      "snapshot has name",
      snapshot.name !== undefined && snapshot.name.length > 0,
    );
    TestValidator.predicate(
      "snapshot has base_price",
      snapshot.base_price !== undefined && snapshot.base_price >= 0,
    );
    TestValidator.predicate(
      "snapshot has timestamp",
      snapshot.snapshot_at !== undefined,
    );
    TestValidator.predicate(
      "snapshot has category",
      snapshot.category !== undefined && snapshot.category.id !== undefined,
    );
    TestValidator.predicate(
      "snapshot has seller",
      snapshot.seller !== undefined && snapshot.seller.id !== undefined,
    );
    TestValidator.predicate(
      "snapshot seller matches product seller",
      snapshot.seller.id === product.seller.id,
    );
  }
  // Verify snapshots captured the state changes
  const snapshotNames = snapshotResponse.data.map((s) => s.name);
  TestValidator.predicate(
    "snapshots include original name",
    snapshotNames.includes(originalName),
  );
  TestValidator.predicate(
    "snapshots include updated name",
    snapshotNames.includes(updatedName),
  );
  const snapshotPrices = snapshotResponse.data.map((s) => s.base_price);
  TestValidator.predicate(
    "snapshots include original price",
    snapshotPrices.includes(originalPrice),
  );
  TestValidator.predicate(
    "snapshots include updated price",
    snapshotPrices.includes(updatedPrice),
  );
}

