export async function test_api_product_snapshot_image_retrieval_by_admin(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create and authenticate admin account
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminConnection: api.IConnection = { host: connection.host };
  const adminJoin = await authorize_admin_join(adminConnection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallAdmin.IJoin,
  });
  typia.assert(adminJoin);
  // Login with same credentials
  const adminLoginConnection: api.IConnection = { host: connection.host };
  const adminLogin = await authorize_admin_login(adminLoginConnection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IShoppingMallAdmin.ILogin,
  });
  typia.assert(adminLogin);
  // 2. Create and authenticate seller account
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerJoin = await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      shop_name: RandomGenerator.name(),
      shop_description: RandomGenerator.paragraph({ sentences: 2 }),
      logo_image_url: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerJoin);
  // Login with same credentials
  const sellerLoginConnection: api.IConnection = { host: connection.host };
  const sellerLogin = await authorize_seller_login(sellerLoginConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ILogin,
  });
  typia.assert(sellerLogin);
  // 3. Admin approves seller registration
  const approvedSeller =
    await api.functional.shoppingMall.admin.sellers.approve(
      adminLoginConnection,
      {
        sellerId: sellerJoin.id,
      },
    );
  typia.assert(approvedSeller);
  TestValidator.equals(
    "seller approval status",
    approvedSeller.approval_status,
    "APPROVED",
  );
  // 4. Seller creates a product (using random UUID for category as placeholder)
  const product = await api.functional.shoppingMall.seller.products.create(
    sellerLoginConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        shopping_category_id: typia.random<string & tags.Format<"uuid">>(),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 5. Seller adds multiple images to product with different display orders
  const imageUrls = ArrayUtil.repeat(5, (index) => ({
    image_url:
      `https://example.com/product-${product.id}-image-${index}.jpg` satisfies string &
        tags.Format<"uri">,
    display_order: index * 10,
  }));
  const createdImages: IShoppingMallProductImage[] = [];
  for (const imageData of imageUrls) {
    const image =
      await api.functional.shoppingMall.seller.products.images.create(
        sellerLoginConnection,
        {
          productId: product.id,
          body: imageData satisfies IShoppingMallProductImage.ICreate,
        },
      );
    typia.assert(image);
    createdImages.push(image);
  }
  TestValidator.equals("image count", createdImages.length, 5);
  // 6. Seller edits product to create a snapshot
  const updatedProduct =
    await api.functional.shoppingMall.seller.products.update(
      sellerLoginConnection,
      {
        productId: product.id,
        body: {
          name: `${product.name} - Updated`,
        } satisfies IShoppingMallProduct.IUpdate,
      },
    );
  typia.assert(updatedProduct);
  // 7. Admin retrieves product snapshots to get snapshot ID
  const snapshots =
    await api.functional.shoppingMall.admin.products.snapshots.index(
      adminLoginConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          limit: 10,
          sort: "snapshot_at,desc",
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );
  typia.assert(snapshots);
  TestValidator.predicate("snapshots exist", snapshots.data.length > 0);
  const snapshot = snapshots.data[0];
  TestValidator.equals(
    "snapshot product name",
    snapshot.name,
    updatedProduct.name,
  );
  // 8. Admin retrieves product snapshot images with default sorting (display_order asc)
  const snapshotImagesDefault =
    await api.functional.shoppingMall.admin.products.snapshots.images.index(
      adminLoginConnection,
      {
        productId: product.id,
        snapshotId: snapshot.id,
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallProductSnapshotImage.IRequest,
      },
    );
  typia.assert(snapshotImagesDefault);
  TestValidator.equals(
    "snapshot images count",
    snapshotImagesDefault.data.length,
    5,
  );
  // Verify images are sorted by display_order ascending
  for (let i = 1; i < snapshotImagesDefault.data.length; i++) {
    TestValidator.predicate(
      `image ${i} display_order >= image ${i - 1}`,
      snapshotImagesDefault.data[i].display_order >=
        snapshotImagesDefault.data[i - 1].display_order,
    );
  }
  // Verify all image URLs match
  const expectedUrls = createdImages.map((img) => img.image_url).sort();
  const actualUrls = snapshotImagesDefault.data
    .map((img) => img.image_url)
    .sort();
  TestValidator.equals("image URLs match", actualUrls, expectedUrls);
  // 9. Test pagination - request page 1 with limit 2
  const snapshotImagesPage1 =
    await api.functional.shoppingMall.admin.products.snapshots.images.index(
      adminLoginConnection,
      {
        productId: product.id,
        snapshotId: snapshot.id,
        body: {
          page: 1,
          limit: 2,
        } satisfies IShoppingMallProductSnapshotImage.IRequest,
      },
    );
  typia.assert(snapshotImagesPage1);
  TestValidator.equals(
    "page 1 image count",
    snapshotImagesPage1.data.length,
    2,
  );
  TestValidator.equals(
    "page 1 current page",
    snapshotImagesPage1.pagination.current,
    1,
  );
  TestValidator.equals("page 1 limit", snapshotImagesPage1.pagination.limit, 2);
  TestValidator.equals(
    "page 1 total records",
    snapshotImagesPage1.pagination.records,
    5,
  );
  TestValidator.equals(
    "page 1 total pages",
    snapshotImagesPage1.pagination.pages,
    3,
  );
  // 10. Test pagination - request page 2 with limit 2
  const snapshotImagesPage2 =
    await api.functional.shoppingMall.admin.products.snapshots.images.index(
      adminLoginConnection,
      {
        productId: product.id,
        snapshotId: snapshot.id,
        body: {
          page: 2,
          limit: 2,
        } satisfies IShoppingMallProductSnapshotImage.IRequest,
      },
    );
  typia.assert(snapshotImagesPage2);
  TestValidator.equals(
    "page 2 image count",
    snapshotImagesPage2.data.length,
    2,
  );
  TestValidator.equals(
    "page 2 current page",
    snapshotImagesPage2.pagination.current,
    2,
  );
  // 11. Test pagination - request page 3 with limit 2 (last page)
  const snapshotImagesPage3 =
    await api.functional.shoppingMall.admin.products.snapshots.images.index(
      adminLoginConnection,
      {
        productId: product.id,
        snapshotId: snapshot.id,
        body: {
          page: 3,
          limit: 2,
        } satisfies IShoppingMallProductSnapshotImage.IRequest,
      },
    );
  typia.assert(snapshotImagesPage3);
  TestValidator.equals(
    "page 3 image count",
    snapshotImagesPage3.data.length,
    1,
  );
  TestValidator.equals(
    "page 3 current page",
    snapshotImagesPage3.pagination.current,
    3,
  );
  // 12. Test sorting by created_at descending
  const snapshotImagesSorted =
    await api.functional.shoppingMall.admin.products.snapshots.images.index(
      adminLoginConnection,
      {
        productId: product.id,
        snapshotId: snapshot.id,
        body: {
          page: 1,
          limit: 20,
          sort: "created_at,desc",
        } satisfies IShoppingMallProductSnapshotImage.IRequest,
      },
    );
  typia.assert(snapshotImagesSorted);
  TestValidator.equals(
    "sorted images count",
    snapshotImagesSorted.data.length,
    5,
  );
  // Verify images are sorted by created_at descending
  for (let i = 1; i < snapshotImagesSorted.data.length; i++) {
    TestValidator.predicate(
      `image ${i} created_at <= image ${i - 1}`,
      new Date(snapshotImagesSorted.data[i].created_at).getTime() <=
        new Date(snapshotImagesSorted.data[i - 1].created_at).getTime(),
    );
  }
  // Verify all images still present regardless of sort order
  const sortedUrls = snapshotImagesSorted.data
    .map((img) => img.image_url)
    .sort();
  TestValidator.equals("sorted image URLs match", sortedUrls, expectedUrls);
}

