  typia.assert(product);
  // 5. Seller uploads multiple images to product (create 8 images for pagination testing)
  const imageUrls: string[] = [];
  for (let i = 0; i < 8; i++) {
    const image =
      await api.functional.shoppingMall.seller.products.images.create(
        sellerConnection,
