export async function test_api_product_snapshot_image_snapshot_integrity(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create admin account and login
  const adminConnection: api.IConnection = { host: connection.host };
  const adminJoin = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Admin1234!",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallAdmin.IJoin,
  });
  typia.assert(adminJoin);
  // 2. Create seller account (automatically logged in via authorize_seller_join)
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerJoin = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Seller1234!",
      shop_name: RandomGenerator.name(),
      shop_description: RandomGenerator.paragraph({ sentences: 2 }),
      logo_image_url: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerJoin);
  // 3. Admin approves seller registration
  const approvedSeller =
    await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
      sellerId: sellerJoin.id,
    });
  typia.assert(approvedSeller);
  TestValidator.equals(
    "seller approval status",
    approvedSeller.approval_status,
    "APPROVED",
  );
  // 4. Seller creates a product with a valid category ID
  // Note: Using a generated UUID for category - in real scenario this would reference an existing category
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const product = await api.functional.shoppingMall.seller.products.create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        shopping_category_id: categoryId,
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 5. Seller uploads multiple images to product (3 images)
  const imageUrls = ArrayUtil.repeat(3, (index) => ({
    image_url:
      `https://example.com/product-${product.id}-image-${index}.jpg` as string &
        tags.Format<"uri">,
    display_order: index,
  }));
  const uploadedImages: IShoppingMallProductImage[] = [];
  for (const imageData of imageUrls) {
    const uploadedImage =
      await api.functional.shoppingMall.seller.products.images.create(
        sellerConnection,
        {
          productId: product.id,
          body: imageData satisfies IShoppingMallProductImage.ICreate,
        },
      );
    typia.assert(uploadedImage);
    uploadedImages.push(uploadedImage);
  }
  TestValidator.equals("uploaded image count", uploadedImages.length, 3);
  // 6. Seller edits product to create first snapshot with all images
  const firstEdit = await api.functional.shoppingMall.seller.products.update(
    sellerConnection,
    {
      productId: product.id,
      body: {
        name: `${product.name} - Updated`,
      } satisfies IShoppingMallProduct.IUpdate,
    },
  );
  typia.assert(firstEdit);
  TestValidator.equals("first edit image count", firstEdit.images.length, 3);
  // 7. Admin retrieves product snapshots to get first snapshot ID
  const snapshotsAfterFirstEdit =
    await api.functional.shoppingMall.admin.products.snapshots.index(
      adminConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          limit: 10,
          sort: "snapshot_at,asc",
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );
  typia.assert(snapshotsAfterFirstEdit);
  TestValidator.predicate(
    "has at least one snapshot",
    snapshotsAfterFirstEdit.data.length >= 1,
  );
  const firstSnapshot = snapshotsAfterFirstEdit.data[0];
  // 8. Retrieve images from first snapshot (should have all 3 images)
  const firstSnapshotImages =
    await api.functional.shoppingMall.admin.products.snapshots.images.index(
      adminConnection,
      {
        productId: product.id,
        snapshotId: firstSnapshot.id,
        body: {
          page: 1,
          limit: 10,
          sort: "display_order,asc",
        } satisfies IShoppingMallProductSnapshotImage.IRequest,
      },
    );
  typia.assert(firstSnapshotImages);
  TestValidator.equals(
    "first snapshot image count",
    firstSnapshotImages.data.length,
    3,
  );
  // Store first snapshot image data for comparison
  const firstSnapshotImageData = firstSnapshotImages.data.map((img) => ({
    id: img.id,
    image_url: img.image_url,
    display_order: img.display_order,
  }));
  // 9. Seller deletes one image from product (delete the second image)
  const imageToDelete = uploadedImages[1];
  await api.functional.shoppingMall.seller.products.images.erase(
    sellerConnection,
    {
      productId: product.id,
      imageId: imageToDelete.id,
    },
  );
  // 10. Seller edits product again to create second snapshot (after image deletion)
  const secondEdit = await api.functional.shoppingMall.seller.products.update(
    sellerConnection,
    {
      productId: product.id,
      body: {
        description: `${product.description ?? ""} - Second update`,
      } satisfies IShoppingMallProduct.IUpdate,
    },
  );
  typia.assert(secondEdit);
  TestValidator.equals("second edit image count", secondEdit.images.length, 2);
  // 11. Admin retrieves product snapshots again to get second snapshot ID
  const snapshotsAfterSecondEdit =
    await api.functional.shoppingMall.admin.products.snapshots.index(
      adminConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          limit: 10,
          sort: "snapshot_at,asc",
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );
  typia.assert(snapshotsAfterSecondEdit);
  TestValidator.predicate(
    "has at least two snapshots",
    snapshotsAfterSecondEdit.data.length >= 2,
  );
  const secondSnapshot = snapshotsAfterSecondEdit.data[1];
  // 12. Retrieve images from second snapshot (should have only 2 images)
  const secondSnapshotImages =
    await api.functional.shoppingMall.admin.products.snapshots.images.index(
      adminConnection,
      {
        productId: product.id,
        snapshotId: secondSnapshot.id,
        body: {
          page: 1,
          limit: 10,
          sort: "display_order,asc",
        } satisfies IShoppingMallProductSnapshotImage.IRequest,
      },
    );
  typia.assert(secondSnapshotImages);
  TestValidator.equals(
    "second snapshot image count",
    secondSnapshotImages.data.length,
    2,
  );
  // 13. Verify first snapshot still has the deleted image
  TestValidator.equals(
    "first snapshot preserves deleted image",
    firstSnapshotImages.data.length,
    3,
  );
  // Verify the deleted image URL is still in first snapshot
  const deletedImageUrl = imageUrls[1].image_url;
  const firstSnapshotHasDeletedImage = firstSnapshotImages.data.some(
    (img) => img.image_url === deletedImageUrl,
  );
  TestValidator.predicate(
    "first snapshot contains deleted image URL",
    firstSnapshotHasDeletedImage,
  );
  // 14. Verify second snapshot does NOT have the deleted image
  const secondSnapshotHasDeletedImage = secondSnapshotImages.data.some(
    (img) => img.image_url === deletedImageUrl,
  );
  TestValidator.predicate(
    "second snapshot does not contain deleted image URL",
    !secondSnapshotHasDeletedImage,
  );
  // 15. Verify image display order is preserved in snapshots
  TestValidator.equals(
    "first snapshot image 0 order",
    firstSnapshotImages.data[0].display_order,
    0,
  );
  TestValidator.equals(
    "first snapshot image 1 order",
    firstSnapshotImages.data[1].display_order,
    1,
  );
  TestValidator.equals(
    "first snapshot image 2 order",
    firstSnapshotImages.data[2].display_order,
    2,
  );
  // 16. Verify snapshot image integrity - URLs are preserved correctly
  TestValidator.equals(
    "first snapshot image 0 URL",
    firstSnapshotImageData[0].image_url,
    imageUrls[0].image_url,
  );
  TestValidator.equals(
    "first snapshot image 1 URL",
    firstSnapshotImageData[1].image_url,
    imageUrls[1].image_url,
  );
  TestValidator.equals(
    "first snapshot image 2 URL",
    firstSnapshotImageData[2].image_url,
    imageUrls[2].image_url,
  );
}

