export async function test_api_order_item_list_filter_by_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer registration and login
  const customerConnection: api.IConnection = { host: connection.host };
  const customerJoin = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Test1234!",
      nickname: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: null,
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customerJoin);
  // 2. Seller registration and login
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerJoin = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Test1234!",
      shop_name: RandomGenerator.name(),
      shop_description: RandomGenerator.paragraph({ sentences: 2 }),
      logo_image_url: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerJoin);
  // 3. Seller creates a product
  const product = await api.functional.shoppingMall.seller.products.create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 1 }),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        shopping_category_id: typia.random<string & tags.Format<"uuid">>(),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 4. Seller creates first variant
  const variant1 =
    await api.functional.shoppingMall.seller.products.variants.create(
      sellerConnection,
      {
        productId: product.id,
        body: {
          sku_code: `SKU-${RandomGenerator.alphaNumeric(8)}`,
          price: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
          stock_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<10>
          >(),
          options: [
            {
              key: "color",
              value: "Red",
            },
          ] satisfies IShoppingMallProductVariantOption.ICreate[],
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(variant1);
  // 5. Seller creates second variant
  const variant2 =
    await api.functional.shoppingMall.seller.products.variants.create(
      sellerConnection,
      {
        productId: product.id,
        body: {
          sku_code: `SKU-${RandomGenerator.alphaNumeric(8)}`,
          price: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
          stock_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<10>
          >(),
          options: [
            {
              key: "color",
              value: "Blue",
            },
          ] satisfies IShoppingMallProductVariantOption.ICreate[],
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(variant2);
  // 6. Customer creates order
  // Note: In production, this would convert cart items to order items
  const order = await api.functional.shoppingMall.customer.orders.create(
    customerConnection,
    {
      body: {
        addressId: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // 7. Seller creates shipment for first item to change its status to SHIPPED
  const firstItemId = order.items[0]?.id;
  if (!firstItemId) {
    throw new Error("Order must have at least one item");
  }
  const shipment = await api.functional.shoppingMall.seller.shipments.create(
    sellerConnection,
    {
      body: {
        order_item_ids: [firstItemId],
        tracking_carrier: "FedEx",
        tracking_number: `TRACK-${RandomGenerator.alphaNumeric(12)}`,
      } satisfies IShoppingMallShipment.ICreate,
    },
  );
  typia.assert(shipment);
  // 8. Filter order items by status=PAID
  const paidItemsResult =
    await api.functional.shoppingMall.customer.orders.items.index(
      customerConnection,
      {
        orderId: order.id,
        body: {
          status: "PAID",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallOrderItem.IRequest,
      },
    );
  typia.assert(paidItemsResult);
  // 9. Verify only PAID items are returned
  TestValidator.predicate(
    "all filtered items have PAID status",
    paidItemsResult.data.every((item) => item.status === "PAID"),
  );
  // 10. Filter order items by status=SHIPPED
  const shippedItemsResult =
    await api.functional.shoppingMall.customer.orders.items.index(
      customerConnection,
      {
        orderId: order.id,
        body: {
          status: "SHIPPED",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallOrderItem.IRequest,
      },
    );
  typia.assert(shippedItemsResult);
  // 11. Verify only SHIPPED items are returned
  TestValidator.predicate(
    "all filtered items have SHIPPED status",
    shippedItemsResult.data.every((item) => item.status === "SHIPPED"),
  );
  // 12. Verify pagination information is correct
  TestValidator.predicate(
    "pagination current page is 1",
    paidItemsResult.pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination limit is 20",
    paidItemsResult.pagination.limit === 20,
  );
  TestValidator.predicate(
    "pagination records count is valid",
    paidItemsResult.pagination.records >= 0,
  );
  // 13. Verify item summary data structure
  if (paidItemsResult.data.length > 0) {
    const firstPaidItem = paidItemsResult.data[0];
    TestValidator.predicate(
      "item has valid quantity",
      firstPaidItem.quantity >= 1,
    );
    TestValidator.predicate(
      "item has valid unit price",
      firstPaidItem.unit_price >= 0,
    );
    TestValidator.equals(
      "item status matches filter",
      firstPaidItem.status,
      "PAID",
    );
  }
  if (shippedItemsResult.data.length > 0) {
    const firstShippedItem = shippedItemsResult.data[0];
    TestValidator.equals(
      "shipped item status matches filter",
      firstShippedItem.status,
      "SHIPPED",
    );
  }
}

