 *
 * This test validates that the GET /shoppingMall/customer/orders/{orderId}/items/{orderItemId}
 * endpoint properly enforces data isolation by:
 * 1. Creating two separate customer accounts
 * 2. Creating a seller account with a product
 * 3. Customer1 places an order
 * 4. Customer2 attempts to access Customer1's order item (should return 404)
 * 5. Customer1 successfully accesses their own order item
 */
export async function test_api_order_item_data_isolation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate Customer1 (order owner)
  const customer1Connection: api.IConnection = { host: connection.host };
  const customer1 = await authorize_customer_join(customer1Connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      nickname: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: null,
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customer1);
