  TestValidator.equals(
    "initial tracking number",
    shipment.tracking_number,
    "123456",
  );
  // 6. Seller updates only tracking_carrier (partial update)
  const updatedShipment =
    await api.functional.shoppingMall.seller.shipments.update(
