 * 3. Customer adds variant to cart
 * 4. Customer creates order from cart
 * 5. Seller creates shipment (items become SHIPPED)
 * 6. Customer retrieves shipment items filtered by SHIPPED status
 * 7. Validate response contains only SHIPPED items
 * 8. Validate pagination metadata matches filtered count
 */
export async function test_api_shipment_items_status_filter(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer authentication
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      nickname: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: null,
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customer);
  // 2. Seller authentication and product creation
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
      shop_description: RandomGenerator.paragraph({ sentences: 2 }),
      logo_image_url: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);
  // 3. Seller creates product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        shopping_category_id: typia.random<string & tags.Format<"uuid">>(),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 4. Seller creates variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku_code: RandomGenerator.alphaNumeric(12),
          price: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
          stock_quantity: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<10> & tags.Maximum<100>
          >(),
          options: ArrayUtil.repeat(2, (index) => ({
            key: index === 0 ? "color" : "size",
            value:
              index === 0
                ? RandomGenerator.alphabets(5)
                : RandomGenerator.alphabets(3),
          })) satisfies IShoppingMallProductVariantOption.ICreate[],
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(variant);
  // 5. Customer adds variant to cart
  const cartItem =
    await generate_random_shopping_mall_customer_customers_cart_items_create(
      customerConnection,
      {
        body: {
          shopping_mall_product_variant_id: variant.id,
          quantity: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);
  // 6. Customer creates order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // 7. Get order item ID for shipment
  const orderItem = order.items[0];
  TestValidator.predicate("order has items", order.items.length > 0);
  // 8. Seller creates shipment
  const shipment = await generate_random_shopping_mall_seller_shipments_create(
    sellerConnection,
    {
      body: {
        order_item_ids: [orderItem.id],
        tracking_carrier: RandomGenerator.alphabets(6),
        tracking_number: RandomGenerator.alphaNumeric(10),
      } satisfies IShoppingMallShipment.ICreate,
    },
  );
  typia.assert(shipment);
  // 9. Customer retrieves shipment items filtered by SHIPPED status
  const shipmentItemsResponse =
    await api.functional.shoppingMall.customer.shipments.items.index(
      customerConnection,
      {
        shipmentId: shipment.id,
        body: {
          status: "SHIPPED",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallShipmentItem.IRequest,
      },
    );
  typia.assert(shipmentItemsResponse);
  // 10. Validate all items have SHIPPED status
  TestValidator.predicate("all items are SHIPPED", () =>
    shipmentItemsResponse.data.every(
      (item) => item.orderItem.status === "SHIPPED",
    ),
  );
  // 11. Validate pagination metadata
  TestValidator.predicate(
    "has pagination",
    shipmentItemsResponse.pagination !== undefined,
  );
  TestValidator.equals(
    "current page",
    shipmentItemsResponse.pagination.current,
    1,
  );
  TestValidator.predicate(
    "limit valid",
    shipmentItemsResponse.pagination.limit >= 1,
  );
  TestValidator.predicate(
    "records match data",
    shipmentItemsResponse.pagination.records ===
      shipmentItemsResponse.data.length,
  );
  TestValidator.predicate(
    "pages calculated",
    shipmentItemsResponse.pagination.pages >= 1,
  );
}

