  const product = await api.functional.shoppingMall.seller.products.create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        shopping_category_id: typia.random<string & tags.Format<"uuid">>(),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 3. Seller creates a product variant
  const variant =
    await api.functional.shoppingMall.seller.products.variants.create(
      sellerConnection,
      {
        productId: product.id,
        body: {
          sku_code: `SKU-${RandomGenerator.alphaNumeric(8)}`,
          price: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
          stock_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<10>
          >(),
          options: [
            {
              key: "color",
              value: RandomGenerator.pick(["Red", "Blue", "Green"]),
            },
            {
              key: "size",
              value: RandomGenerator.pick(["S", "M", "L", "XL"]),
            },
          ] satisfies IShoppingMallProductVariantOption.ICreate[],
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(variant);
  // 4. Create and authenticate customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "CustomerPass123!",
      nickname: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: null,
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  // 5. Customer adds variant to cart
  const cartItem =
    await api.functional.shoppingMall.customer.customers.cart.items.create(
      customerConnection,
      {
        body: {
          shopping_mall_product_variant_id: variant.id,
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);
  // 6. Customer creates order
  const order = await api.functional.shoppingMall.customer.orders.create(
    customerConnection,
    {
      body: {
        addressId: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // 7. Validate order has items
  TestValidator.predicate("order has items", order.items.length > 0);
  // 8. Get the first order item (should be from our seller's product)
  const orderItem = order.items[0];
  // 9. Seller retrieves order item details
  const retrievedOrderItem =
    await api.functional.shoppingMall.seller.orders.items.at(sellerConnection, {
      orderId: order.id,
      itemId: orderItem.id,
    });
  typia.assert(retrievedOrderItem);
  // 10. Validate order item contains current product variant information
  TestValidator.equals(
    "variant ID matches",
    retrievedOrderItem.productVariant.id,
    variant.id,
  );
  TestValidator.equals(
    "SKU code matches",
    retrievedOrderItem.productVariant.skuCode,
    variant.skuCode,
  );
  // 11. Validate historical product snapshot is preserved
  TestValidator.equals(
    "product snapshot name matches",
    retrievedOrderItem.productSnapshot.name,
    product.name,
  );
  TestValidator.equals(
    "product snapshot base price matches",
    retrievedOrderItem.productSnapshot.base_price,
    product.base_price,
  );
  TestValidator.equals(
    "product snapshot category matches",
    retrievedOrderItem.productSnapshot.category.id,
    product.category.id,
  );
  // 12. Validate historical product variant snapshot preserves configuration
  TestValidator.equals(
    "variant snapshot SKU matches",
    retrievedOrderItem.productVariantSnapshot.sku_code,
    variant.skuCode,
  );
  TestValidator.predicate(
    "variant snapshot has options",
    Object.keys(retrievedOrderItem.productVariantSnapshot.option_values)
      .length > 0,
  );
  // 13. Validate seller information is included
  TestValidator.equals(
    "seller ID matches",
    retrievedOrderItem.seller.id,
    sellerAuth.id,
  );
  TestValidator.equals(
    "seller shop name matches",
    retrievedOrderItem.seller.shop_name,
    sellerAuth.shop_name,
  );
  // 14. Validate order item status
  TestValidator.predicate(
    "order item has valid status",
    ["PAID", "SHIPPED", "DELIVERED", "CANCELLED", "REFUNDED"].includes(
      retrievedOrderItem.status,
    ),
  );
  // 15. Validate quantity and unit price match original order
  TestValidator.equals(
    "quantity matches",
    retrievedOrderItem.quantity,
    orderItem.quantity,
  );
  TestValidator.equals(
    "unit price matches",
    retrievedOrderItem.unitPrice,
    orderItem.unitPrice,
  );
  // 16. Validate order reference
  TestValidator.equals(
    "order ID matches",
    retrievedOrderItem.order.id,
    order.id,
  );
  TestValidator.equals(
    "order number matches",
    retrievedOrderItem.order.orderNumber,
    order.order_number,
  );
}

