      itemId: orderItem.id,
    });
  typia.assert(retrievedOrderItem);
  // ============================================================================
  // 9. VERIFY SNAPSHOTS CONTAIN ORIGINAL STATE (NOT UPDATED STATE)
  // ============================================================================
