export async function test_api_review_snapshot_after_review_deletion(
  connection: api.IConnection,
): Promise<void> {
  // 1. Setup: Create seller account and register
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerJoin = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234",
      shop_name: RandomGenerator.name(),
      shop_description: RandomGenerator.paragraph({ sentences: 2 }),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerJoin);
  // 2. Setup: Create customer account and register
  const customerConnection: api.IConnection = { host: connection.host };
  const customerJoin = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234",
      nickname: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: null,
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customerJoin);
  // 3. Seller creates a product
  const product = await api.functional.shoppingMall.seller.products.create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        shopping_category_id: typia.random<string & tags.Format<"uuid">>(),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 4. Customer creates a review (assuming delivered order item exists)
  // Note: In a real scenario, this would require: cart → order → shipment → delivery
  // For this test, we create a review directly using a valid order item ID
  const review =
    await api.functional.shoppingMall.customer.customers.order_items.review.create(
      customerConnection,
      {
        orderItemId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          rating: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
          content: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IShoppingMallReview.ICreate,
      },
    );
  typia.assert(review);
  // 5. Customer edits the review to create a snapshot
  const updatedReview =
    await api.functional.shoppingMall.customer.reviews.update(
      customerConnection,
      {
        reviewId: review.id,
        body: {
          rating: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
          content: RandomGenerator.paragraph({ sentences: 4 }),
        } satisfies IShoppingMallReview.IUpdate,
      },
    );
  typia.assert(updatedReview);
  // 6. Customer deletes the review (soft delete)
  await api.functional.shoppingMall.customer.reviews.erase(customerConnection, {
    reviewId: review.id,
  });
  // 7. Seller authenticates to access review snapshots
  const sellerLoginConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerLoginConnection, {
    body: {
      email: sellerJoin.email,
      password: "1234",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: undefined,
    } satisfies IShoppingMallSeller.ILogin,
  });
  // 8. Seller calls PATCH endpoint to get snapshots of deleted review
  const snapshots =
    await api.functional.shoppingMall.customer.reviews.snapshots.index(
      sellerLoginConnection,
      {
        reviewId: review.id,
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallReviewSnapshot.IRequest,
      },
    );
  typia.assert(snapshots);
  // 9. Validate snapshots are preserved after review deletion
  TestValidator.predicate(
    "snapshots exist after review deletion",
    snapshots.data.length > 0,
  );
  TestValidator.equals(
    "pagination current page",
    snapshots.pagination.current,
    1,
  );
  TestValidator.predicate(
    "pagination records count is valid",
    snapshots.pagination.records >= snapshots.data.length,
  );
  // 10. Validate snapshot data integrity (typia.assert already validates structure)
  const firstSnapshot = snapshots.data[0];
  TestValidator.predicate(
    "snapshot rating is valid (1-5)",
    firstSnapshot.rating >= 1 && firstSnapshot.rating <= 5,
  );
  TestValidator.predicate(
    "snapshot has snapshot_at timestamp",
    firstSnapshot.snapshot_at !== null &&
      firstSnapshot.snapshot_at !== undefined,
  );
  TestValidator.equals(
    "snapshot user is the customer who wrote the review",
    firstSnapshot.snapshotByUser.id,
    customerJoin.id,
  );
  // 11. Verify business rule: snapshots preserved independently of review deletion
  TestValidator.predicate(
    "snapshots preserved after soft delete",
    snapshots.data.every(
      (s) =>
        s.id !== null &&
        s.rating >= 1 &&
        s.rating <= 5 &&
        s.snapshot_at !== null,
    ),
  );
}

