  TestValidator.predicate(
    "current page is 1",
    response.pagination.current === 1,
  );
  TestValidator.predicate("limit is 20", response.pagination.limit === 20);
  TestValidator.predicate(
    "records count is non-negative",
    response.pagination.records >= 0,
