      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: null,
    },
  });
  typia.assert(customer);
  // 7. Customer adds variant to cart
  const cartItem =
    await api.functional.shoppingMall.customer.customers.cart.items.create(
      customerConnection,
      {
        body: {
          shopping_mall_product_variant_id: variant.id,
          quantity: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);
  // 8. Customer places order
  const order = await api.functional.shoppingMall.customer.orders.create(
    customerConnection,
    {
      body: {
        addressId: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  TestValidator.predicate("order has items", order.items.length > 0);
  const orderItem = order.items[0];
  TestValidator.equals("order item status", orderItem.status, "PAID");
  // 9. Seller creates shipment
  const shipment = await api.functional.shoppingMall.seller.shipments.create(
    sellerConnection,
    {
      body: {
        order_item_ids: [orderItem.id],
        tracking_carrier: "TestCarrier",
        tracking_number: `TRACK-${RandomGenerator.alphaNumeric(10)}`,
      } satisfies IShoppingMallShipment.ICreate,
    },
  );
  typia.assert(shipment);
  // 10. Customer confirms delivery
  const confirmedShipment =
    await api.functional.shoppingMall.customer.shipments.confirm_delivery.confirmDelivery(
      customerConnection,
      {
        shipmentId: shipment.id,
      },
    );
  typia.assert(confirmedShipment);
  TestValidator.predicate(
    "shipment delivery confirmed",
    confirmedShipment.delivery_confirmed_at !== null,
  );
  // 11. Customer writes review for delivered order item
  const review =
    await api.functional.shoppingMall.customer.customers.order_items.review.create(
      customerConnection,
      {
        orderItemId: orderItem.id,
        body: {
          rating: 5,
          content: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IShoppingMallReview.ICreate,
      },
    );
  typia.assert(review);
  TestValidator.equals("review rating", review.rating, 5);
  // 12. Customer edits review (this creates a snapshot)
  const updatedReview =
    await api.functional.shoppingMall.customer.reviews.update(
      customerConnection,
      {
        reviewId: review.id,
        body: {
          rating: 4,
          content: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies IShoppingMallReview.IUpdate,
      },
    );
  typia.assert(updatedReview);
  TestValidator.notEquals(
    "review was updated",
    updatedReview.updated_at,
    review.updated_at,
  );
  // 13. Customer deletes review (soft delete)
  await api.functional.shoppingMall.customer.reviews.erase(customerConnection, {
    reviewId: review.id,
  });
  // 14. Seller retrieves review snapshot
  // Note: In production, snapshotId would be obtained from a list snapshots endpoint.
  // This test validates that the snapshot endpoint is accessible to sellers even after
  // the parent review has been soft deleted, ensuring audit trail integrity.
  // For this test, we use a generated UUID to demonstrate the endpoint structure.
  // In a real scenario, the snapshot ID would come from listing review snapshots.
  const snapshotId = typia.random<string & tags.Format<"uuid">>();
  // This call validates that sellers can access review snapshots for compliance
  // and dispute resolution purposes, even when reviews have been deleted by customers
  const snapshot =
    await api.functional.shoppingMall.seller.reviews.snapshots.at(
      sellerConnection,
      {
        reviewId: review.id,
        snapshotId: snapshotId,
      },
    );
  typia.assert(snapshot);
  // Validate snapshot structure and integrity
  TestValidator.equals("snapshot review ID", snapshot.review.id, review.id);
  TestValidator.predicate(
    "snapshot has valid rating",
    snapshot.rating >= 1 && snapshot.rating <= 5,
  );
  TestValidator.predicate(
    "snapshot has content field",
    snapshot.content !== undefined,
  );
  TestValidator.predicate(
    "snapshot has timestamp",
    snapshot.snapshot_at !== null,
  );
  TestValidator.predicate(
    "snapshot has user info",
    snapshot.snapshotByUser !== null,
  );
  TestValidator.predicate(
    "snapshot created after review",
    snapshot.snapshot_at >= review.created_at,
  );
}

