  // Validate orderItem status reflects cancellation outcome (CANCELLED if approved)
  if (retrievedRequest.status === "APPROVED") {
    TestValidator.equals(
      "order item status is CANCELLED",
      retrievedRequest.orderItem.status,
      "CANCELLED",
    );
  }
