export async function putShoppingMallSellerRefundRequestsRefundRequestId(props: {
  seller: SellerPayload;
  refundRequestId: string & tags.Format<"uuid">;
  body: IShoppingMallRefundRequest.IUpdate;
}): Promise<IShoppingMallRefundRequest> {
  const refundRequest =
    await MyGlobal.prisma.shopping_mall_refund_requests.findUniqueOrThrow({
      where: { id: props.refundRequestId },
      select: {
        id: true,
        status: true,
        reason: true,
        customer_id: true,
        delivered_at: true,
        requested_at: true,
        orderItem: {
          select: {
            id: true,
            shopping_mall_seller_id: true,
            shopping_mall_product_variant_id: true,
          },
        },
      },
    });
  if (refundRequest.status !== "PENDING") {
    throw new HttpException("Refund request is not in PENDING status", 400);
  }
  if (refundRequest.orderItem.shopping_mall_seller_id !== props.seller.id) {
    throw new HttpException(
      "Forbidden: Not the seller of this order item",
      403,
    );
  }
  if (
    !props.body.status ||
    (props.body.status !== "APPROVED" && props.body.status !== "REJECTED")
  ) {
    throw new HttpException("Status must be either APPROVED or REJECTED", 400);
  }
  const now = new Date();
  await MyGlobal.prisma.shopping_mall_refund_requests.update({
    where: { id: props.refundRequestId },
    data: {
      status: props.body.status,
      responded_by_seller_id: props.seller.id,
      responded_at: now,
      updated_at: now,
    },
  });
  await MyGlobal.prisma.shopping_mall_refund_request_snapshots.create({
    data: {
      id: v4(),
      refundRequest: { connect: { id: props.refundRequestId } },
      orderItem: { connect: { id: refundRequest.orderItem.id } },
      customer: { connect: { id: refundRequest.customer_id } },
      status: props.body.status,
      reason: refundRequest.reason,
      delivered_at: refundRequest.delivered_at,
      requested_at: refundRequest.requested_at,
      responded_at: now,
      respondedBySeller: { connect: { id: props.seller.id } },
      snapshot_at: now,
      created_at: now,
    },
  });
  if (props.body.status === "APPROVED") {
    await MyGlobal.prisma.shopping_mall_order_items.update({
      where: { id: refundRequest.orderItem.id },
      data: {
        status: "REFUNDED",
        updated_at: now,
      },
    });
    await MyGlobal.prisma.shopping_mall_inventory_records.create({
      data: {
        id: v4(),
        variant: {
          connect: {
            id: refundRequest.orderItem.shopping_mall_product_variant_id,
          },
        },
        quantity_change: 1,
        reason: "REFUND",
        created_at: now,
      },
    });
  }
  const updated =
    await MyGlobal.prisma.shopping_mall_refund_requests.findUniqueOrThrow({
      where: { id: props.refundRequestId },
      ...ShoppingMallRefundRequestTransformer.select(),
    });
  return await ShoppingMallRefundRequestTransformer.transform(updated);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteShoppingMallSellerProductsProductIdImagesImageId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  imageId: string & tags.Format<"uuid">;
}): Promise<void> {
  const product =
    await MyGlobal.prisma.shopping_mall_products.findUniqueOrThrow({
      where: { id: props.productId },
      select: {
        id: true,
        shopping_seller_id: true,
        shopping_category_id: true,
        name: true,
        description: true,
        base_price: true,
        deleted: true,
      },
    });
  if (product.shopping_seller_id !== props.seller.id) {
    throw new HttpException("Forbidden", 403);
  }
  if (product.deleted) {
    throw new HttpException("Product is deleted", 400);
  }
  const image =
    await MyGlobal.prisma.shopping_mall_product_images.findUniqueOrThrow({
      where: { id: props.imageId },
      select: {
        id: true,
        shopping_mall_product_id: true,
        deleted_at: true,
      },
    });
  if (image.shopping_mall_product_id !== props.productId) {
    throw new HttpException("Image does not belong to this product", 400);
  }
  if (image.deleted_at !== null) {
    throw new HttpException("Image is already deleted", 400);
  }
  const snapshotId = v4() as string & tags.Format<"uuid">;
  await MyGlobal.prisma.shopping_mall_product_snapshots.create({
    data: {
      id: snapshotId,
      shopping_mall_product_id: props.productId,
      shopping_mall_category_id: product.shopping_category_id,
      shopping_mall_seller_id: props.seller.id,
      name: product.name,
      description: product.description ?? "",
      base_price: product.base_price,
      snapshot_at: new Date(),
      created_at: new Date(),
    },
  });
  const activeImages =
    await MyGlobal.prisma.shopping_mall_product_images.findMany({
      where: {
        shopping_mall_product_id: props.productId,
        deleted_at: null,
      },
      orderBy: { display_order: "asc" },
    });
  await MyGlobal.prisma.shopping_mall_product_snapshot_images.createMany({
    data: activeImages.map((img, index) => ({
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_product_snapshot_id: snapshotId,
      image_url: img.image_url,
      display_order: index,
      created_at: new Date(),
    })),
  });
  await MyGlobal.prisma.shopping_mall_product_images.update({
    where: { id: props.imageId },
    data: {
      deleted_at: new Date(),
      updated_at: new Date(),
    },
  });
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteShoppingMallSellerProductsProductIdVariantsVariantIdOptionsOptionId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  variantId: string & tags.Format<"uuid">;
  optionId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Verify product exists and seller owns it
  const product =
    await MyGlobal.prisma.shopping_mall_products.findUniqueOrThrow({
      where: { id: props.productId },
      select: { id: true, shopping_seller_id: true },
    });
  if (product.shopping_seller_id !== props.seller.id) {
    throw new HttpException("Forbidden: You do not own this product", 403);
  }
  // Verify variant exists and belongs to product
  const variant =
    await MyGlobal.prisma.shopping_mall_product_variants.findUniqueOrThrow({
      where: { id: props.variantId },
      select: { id: true, shopping_mall_product_id: true },
    });
  if (variant.shopping_mall_product_id !== props.productId) {
    throw new HttpException("Variant does not belong to this product", 404);
  }
  // Verify option exists and belongs to variant
  const option =
    await MyGlobal.prisma.shopping_mall_product_variant_options.findUniqueOrThrow(
      {
        where: { id: props.optionId },
        select: { id: true, shopping_mall_product_variant_id: true },
      },
    );
  if (option.shopping_mall_product_variant_id !== props.variantId) {
    throw new HttpException("Option does not belong to this variant", 404);
  }
  // Check for pending order items (PAID or SHIPPED status) for this variant
  const pendingOrderItems =
    await MyGlobal.prisma.shopping_mall_order_items.findFirst({
      where: {
        shopping_mall_product_variant_id: props.variantId,
        status: { in: ["PAID", "SHIPPED"] },
        deleted_at: null,
      },
    });
  if (pendingOrderItems) {
    throw new HttpException(
      "Cannot delete option: Variant has pending order items",
      409,
    );
  }
  // Check for pending cancellation requests for order items of this variant
  const pendingCancellationRequests =
    await MyGlobal.prisma.shopping_mall_cancellation_requests.findFirst({
      where: {
        orderItem: {
          shopping_mall_product_variant_id: props.variantId,
          deleted_at: null,
        },
        status: "PENDING",
        deleted_at: null,
      },
    });
  if (pendingCancellationRequests) {
    throw new HttpException(
      "Cannot delete option: Variant has pending cancellation requests",
      409,
    );
  }
  // Check for pending refund requests for order items of this variant
  const pendingRefundRequests =
    await MyGlobal.prisma.shopping_mall_refund_requests.findFirst({
      where: {
        orderItem: {
          shopping_mall_product_variant_id: props.variantId,
          deleted_at: null,
        },
        status: "PENDING",
        deleted_at: null,
      },
    });
  if (pendingRefundRequests) {
    throw new HttpException(
      "Cannot delete option: Variant has pending refund requests",
      409,
    );
  }
  // Delete the option record
  await MyGlobal.prisma.shopping_mall_product_variant_options.delete({
    where: { id: props.optionId },
  });
}

