      price: cartItem.variant.price ?? undefined,
      stockQuantity: cartItem.variant.stock_quantity,
    },
    createdAt: toISOStringSafe(cartItem.created_at),
    updatedAt: toISOStringSafe(cartItem.updated_at),
  };
}

