      created_at: { lte: new Date(props.body.date_to) },
    }),
  } satisfies Prisma.shopping_mall_order_itemsWhereInput;
  const validSortFields = [
    "created_at",
    "status",
    "quantity",
    "unit_price",
    "updated_at",
  ] as const;
  const sortParts = props.body.sort?.split(",") ?? [];
