import { AdminAuth } from "../../../../../decorators/AdminAuth";
import { AdminPayload } from "../../../../../decorators/payload/AdminPayload";
import { deleteShoppingMallAdminAdminCategoriesCategoryId } from "../../../../../providers/deleteShoppingMallAdminAdminCategoriesCategoryId";

@Controller("/shoppingMall/admin/admin/categories/:categoryId")
export class ShoppingmallAdminAdminCategoriesController {
  /**
   * Soft delete a product category from the shopping mall classification system by marking it as deleted.
   *
   * This operation marks a category as deleted by setting its deleted_at timestamp. Only administrators (regular admins and super admins) can delete categories. Before deletion, the system validates that the category has no subcategories - administrators must first remove or reassign all subcategories before deleting a parent category.
   *
   * When a category is soft deleted, all products assigned to that category become uncategorized. Uncategorized products remain in the system and are still visible in search results, but they no longer appear in category browsing. Product snapshots and order item snapshots preserve the category assignment at the time of their creation, ensuring historical accuracy for past orders and product versions.
   *
   * The soft delete operation sets the deleted_at timestamp and can potentially be reversed by administrators if needed. This operation requires administrator authentication and authorization.
   *
   * @param connection
   * @param categoryId Target category's UUID identifier (global scope)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Delete a category by setting its deleted_at timestamp (soft delete). Verify the requesting user is an administrator (admin or superAdmin role). Check that the category exists and is not already deleted. Before deletion, validate that the category has no subcategories - if subcategories exist, reject the request with an error indicating subcategories must be removed or reassigned first. Query the products table to count how many products will become uncategorized and include this in the warning response. Update the category's deleted_at field to current timestamp. Preserve all historical snapshots (product snapshots, order item snapshots) which maintain the category assignment at the time of snapshot creation. Return success with no content. Handle concurrent deletion attempts with optimistic locking on updated_at timestamp.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete()
  public async erase(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("categoryId")
    categoryId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteShoppingMallAdminAdminCategoriesCategoryId({
        admin,
        categoryId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

