   */
  @TypedRoute.Patch()
  public async reorder(
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallProductImage.IReorder,
  ): Promise<IShoppingMallProductImage> {
    try {
      return await patchShoppingMallProductsProductIdImages({
        productId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed information about a specific product image.
   *
   * This operation returns complete information about a single product image including its URL reference, display order within the product's image gallery, and creation/update timestamps. Product images provide visual representation for product listings and are displayed on product detail pages in the seller-defined order.
   *
   * The image is accessed through its parent product context, ensuring proper scope and relationship validation. Only active (non-deleted) images are returned. Deleted images remain accessible through product snapshots for historical accuracy.
   *
   * This endpoint is used when customers view product detail pages or when sellers manage their product image galleries. The response includes all image attributes needed for display and management operations.
