   * 2. Verify shopping_mall_review_id matches the provided reviewId path parameter
   * 3. Enforce authorization: current user must be review owner (snapshot_by_user_id), seller of the product, or administrator
   * 4. Join with shopping_mall_reviews to verify review context (even if soft deleted)
   * 5. Join with shopping_mall_products through review to validate seller access
   * 6. Return snapshot with all fields: id, rating, content, snapshot_at, created_at, snapshotByUser info
   *
   * Edge cases:
   * - Snapshot not found: return 404
   * - ReviewId mismatch: return 404 (don't expose existence)
   * - Unauthorized access: return 403
   * - Review soft deleted: still allow access per requirements (section 347)
   *
   * Transaction: Read-only query, no transaction needed.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":snapshotId")
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("reviewId")
    reviewId: string & tags.Format<"uuid">,
    @TypedParam("snapshotId")
    snapshotId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallReviewSnapshot> {
    try {
      return await getShoppingMallCustomerReviewsReviewIdSnapshotsSnapshotId({
        customer,
        reviewId,
        snapshotId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

