import { IPageIShoppingMallCancellationRequestSnapshot } from "../../../../../api/structures/IPageIShoppingMallCancellationRequestSnapshot";
import { CustomerAuth } from "../../../../../decorators/CustomerAuth";
import { CustomerPayload } from "../../../../../decorators/payload/CustomerPayload";
import { getShoppingMallCustomerCancellationRequestsRequestIdSnapshots } from "../../../../../providers/getShoppingMallCustomerCancellationRequestsRequestIdSnapshots";

@Controller("/shoppingMall/customer/cancellation-requests/:requestId/snapshots")
export class ShoppingmallCustomerCancellation_requestsSnapshotsController {
  /**
   * Retrieve the complete chronological history of cancellation request snapshots for audit trail and dispute resolution.
   *
   * This endpoint returns all snapshots created for a specific cancellation request, showing the evolution of the request state from submission through seller response. Each snapshot captures the exact state of the cancellation request at a point in time, including the reason, status, and response details. Snapshots are created automatically when the seller responds to the cancellation request and cannot be modified or deleted.
   *
   * Access is restricted based on user role and relationship to the request: customers can view snapshots for their own cancellation requests, sellers can view snapshots for requests on their order items, and administrators can view any cancellation request snapshots. This ensures transparent dispute resolution while maintaining appropriate data isolation.
   *
   * The response includes snapshot metadata such as the status at capture time, seller response information, and timestamps. Results are ordered chronologically by creation time to show the complete audit trail. The endpoint returns the full snapshot history for the specified cancellation request.
   *
   * @param connection
   * @param requestId Target cancellation request's ID (UUID format)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query shopping_mall_cancellation_request_snapshots table filtering by cancellation_request_id parameter. Join with shopping_mall_sellers table to include responder information when responded_by_seller_id is not null. Order results by created_at ascending to show chronological history. Validate that the authenticated user has permission to view this cancellation request: customer must be the request submitter, seller must be the responder, or user must have admin role. Return 404 if cancellation request not found. Return 403 if user lacks permission. Snapshots are immutable so no write operations are allowed on this endpoint.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("requestId")
    requestId: string & tags.Format<"uuid">,
  ): Promise<IPageIShoppingMallCancellationRequestSnapshot.ISummary> {
    try {
      return await getShoppingMallCustomerCancellationRequestsRequestIdSnapshots(
        {
          customer,
          requestId,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

